package com.assetflow.api;
import jakarta.servlet.http.*;import org.springframework.http.*;import org.springframework.security.authentication.*;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.core.Authentication;import org.springframework.security.core.AuthenticationException;import org.springframework.security.core.context.*;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/v1/auth")public class AuthController{private final AuthenticationManager manager;public AuthController(AuthenticationConfiguration c)throws Exception{manager=c.getAuthenticationManager();}public record Login(String username,String password){}
@PostMapping("/login")public ResponseEntity<?>login(@RequestBody Login x,HttpServletRequest req,HttpServletResponse res){try{Authentication a=manager.authenticate(new UsernamePasswordAuthenticationToken(x.username(),x.password()));SecurityContext c=SecurityContextHolder.createEmptyContext();c.setAuthentication(a);SecurityContextHolder.setContext(c);new HttpSessionSecurityContextRepository().saveContext(c,req,res);return ResponseEntity.ok(Map.of("username",a.getName()));}catch(AuthenticationException e){return ResponseEntity.status(401).body(Map.of("error","아이디 또는 비밀번호가 올바르지 않습니다."));}}
@GetMapping("/me")public ResponseEntity<?>me(Authentication a){return a==null?ResponseEntity.status(401).build():ResponseEntity.ok(Map.of("username",a.getName()));}@PostMapping("/logout")public Map<String,String>logout(HttpServletRequest req){var s=req.getSession(false);if(s!=null)s.invalidate();SecurityContextHolder.clearContext();return Map.of("status","ok");}}
